use vstd::prelude::*;

verus! {

    // Specification of the alternating‐sign prefix sum S on non‐negative integers.
    //   S(k) = k/2        if k is even
    //        = −(k+1)/2  if k is odd
    spec fn S(k: nat) -> int
        decreases k
    {
        if k % 2 == 0 {
            (k / 2) as int
        } else {
            -((k + 1) / 2) as int
        }
    }

    // For each query (l, r) with 1 ≤ l ≤ r, we return S(r) − S(l−1), packed into an i8.
    fn solve(queries: Vec<(i8, i8)>) -> Vec<i8>
        requires
            // all queries satisfy 1 ≤ l ≤ r
            forall |i: usize| 0 <= i && i < queries.len() ==>
                let (l, r) = queries.index(i);
                1 <= l && l <= r
        ensures
            // output has same length
            result.len() == queries.len(),
            // and for each position i the result is exactly S(r) − S(l−1)
            forall |i: usize| 0 <= i && i < result.len() ==>
                let (l, r) = queries.index(i);
                (result.index(i) as int) == S(r as nat) - S((l - 1) as nat)
    {
        let n = queries.len();
        let mut res: Vec<i8> = Vec::empty();
        res.reserve(n);
        let mut idx: usize = 0;

        // We iterate over all queries, maintaining that we've
        // correctly filled res[0..idx] so far.
        while idx < n
            invariant
                idx <= n,
                res.len() == idx,
                // for all j < idx the j‐th answer is already correct
                forall |j: usize| 0 <= j && j < idx ==>
                    let (lj, rj) = queries.index(j);
                    (res.index(j) as int) == S(rj as nat) - S((lj - 1) as nat),
            decreases n - idx
        {
            let (l, r) = queries.index(idx);

            //
            // We compute S(r) and S(l-1) in a way that never overflows:
            //   - cast to i16 so that r+1≤128 is safe,
            //   - do the formula,
            //   - subtract,
            //   - cast back to i8 (the final result is in [−128..127] by a simple bound argument).
            //
            let l16: i16 = l as i16;
            let r16: i16 = r as i16;

            let S_r: i16 =
                if r16 % 2 == 0 {
                    r16 / 2
                } else {
                    -((r16 + 1) / 2)
                };

            let l1: i16 = l16 - 1;
            let S_l1: i16 =
                if l1 % 2 == 0 {
                    l1 / 2
                } else {
                    -((l1 + 1) / 2)
                };

            let ans16: i16 = S_r - S_l1;
            let ans: i8 = ans16 as i8;

            res.push(ans);
            idx += 1;
        }

        res
    }

} // verus!

